#board {
    display: flex;
    gap: 20px;
    padding: 20px;
}

.column {
    flex: 1;
    border: 1px solid #ccc;
    border-radius: 5px;
    padding: 10px;
    min-height: 300px;
}

.column h2 {
    margin-top: 0;
}

.card {
    background-color: #fff;
    border: 1px solid #999;
    border-radius: 5px;
    padding: 10px;
    margin-bottom: 10px;
    cursor: move;
}

.dragging {
    opacity: 0.5;
}

.placeholder {
    height: 60px;
    border: 2px dashed #ccc;
    border-radius: 5px;
    margin-bottom: 10px;
}

