      const column = boardState.find(c => c.id === columnId);
      if (column) {
        const tempCardIndex = column.cards.findIndex(c => c.id.startsWith('temp-'));
        if (tempCardIndex !== -1) {
          column.cards[tempCardIndex] = serverCard;
