    if (sourceColumn && targetColumn) {
      // Remove from source column
      const sourceIndex = sourceColumn.cards.findIndex(c => c.id === draggedCard.id);
      if (sourceIndex !== -1) {
        sourceColumn.cards.splice(sourceIndex, 1);
      }

      // Add to target column
      if (beforeId) {
