      const column = boardState.find(c => c.id === columnId);
      if (column) {
        column.cards = cards;
        renderBoard();
      }
    });

    eventSource.onerror = (error) => {
      console.error('SSE error:', error);
      eventSource.close();
      // Try to reconnect after a delay
      setTimeout(initSSE, 3000);
