  const boardElement = document.getElementById('board');
  let boardState = [];
  let draggedCard = null;
  let dragOverColumn = null;
  let dragOverCard = null;

  // Fetch initial board state
  fetch('/api/board')
    .then(response => response.json())
    .then(data => {
