          return {
            ...col,
            cards: col.cards.map(c => c.id === card.id ? card : c)
          };
        } else if (col.id === card.column_id) {
          // Card just moved to this column - add it
          return {
            ...col,
            cards: [...col.cards, card]
          };
        } else if (col.id !== card.column_id && col.id !== columnId) {
