      const existingPlaceholder = columnElement.querySelector('.placeholder');
      if (existingPlaceholder) {
        existingPlaceholder.remove();
      }

      // Create a placeholder at the drop position
      const cardElement = e.target.closest('.card');
      if (cardElement) {
