          return {
            ...col,
            cards: [...col.cards, card]
          };
        } else if (col.id !== card.column_id && col.id !== columnId) {
          // Card was in this column but moved away - remove it
          return {
            ...col,
            cards: col.cards.filter(c => c.id !== card.id)
          };
        }
        return col;
      });

      renderBoard();
    });

