    eventSource.onmessage = (event) => {
      console.log('Received message:', event.data);
    };

    eventSource.addEventListener('cardCreated', (event) => {
      const card = JSON.parse(event.data);
      const column = boardState.find(c => c.id === card.column_id);

      if (column) {
