          };
        }
        return col;
      });

      renderBoard();
    })
    .catch(error => {
      console.error('Error moving card:', error);
      // Revert optimistic UI update
      const sourceColumn = boardState.find(c => c.id === draggedCard.column_id);
      const targetColumn = boardState.find(c => c.id === targetColumnId);

      if (sourceColumn) {
