        if (tempCardIndex !== -1) {
          column.cards[tempCardIndex] = card;
        } else {
          // Add the new card to the end of the column
          column.cards.push(card);
        }

        renderBoard();
      }
    });

    eventSource.addEventListener('cardMoved', (event) => {
      const data = JSON.parse(event.data);
