{"path": "/tmp/runs/smokes/seed-q4/kanban-board/interactive/runs/201/app/kanban-board/src/db.js", "content": "import { PGlite } from '@electric-sql/pglite';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dbPath = path.join(__dirname, '../data/db');

let db;

// Initialize the database connection
export async function initDB() {
  db = new PGlite({ 
    auth: { mode: 'trust' },
    path: dbPath
  });

  // Create tables if they don't exist
  await createTables();

  // Seed default columns if none exist
  await seedDefaultColumns();

  return db;
}

// Create columns and cards tables
async function createTables() {
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL,
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (column_id) REFERENCES columns(id) ON DELETE CASCADE
    );
  `);
}

// Seed default columns
async function seedDefaultColumns() {
  const count = await db.oneFirst('SELECT COUNT(*) FROM columns');

  if (count === 0) {
    await db.exec(`
      INSERT INTO columns (id, title, position) VALUES
        ('todo', 'To Do', 1),
        ('in-progress', 'In Progress', 2),
        ('done', 'Done', 3);
    `);
  }
}

// Get all columns with their cards, ordered by position
export async function getBoardState() {
  const columns = await db.all('SELECT * FROM columns ORDER BY position');

  for (let column of columns) {
    const cards = await db.all(
      'SELECT * FROM cards WHERE column_id = $1 ORDER BY position',
      [column.id]
    );
    column.cards = cards;
  }

  return columns;
}

// Create a new card in a column
export async function createCard(columnId, text) {
  const id = crypto.randomUUID();
  const position = await getNextCardPosition(columnId);

  await db.exec(
    'INSERT INTO cards (id, column_id, text, position) VALUES ($1, $2, $3, $4)',
    [id, columnId, text, position]
  );

  return getCardById(id);
}

// Get the next position for a new card in a column
async function getNextCardPosition(columnId) {
  const result = await db.oneFirst(
    'SELECT MAX(position) FROM cards WHERE column_id = $1',
    [columnId]
  );

  return result ? result + 1 : 1;
}

// Get a card by ID
export async function getCardById(id) {
  return db.one('SELECT * FROM cards WHERE id = $1', [id]);
}

// Move a card to a new column and/or position
export async function moveCard(cardId, targetColumnId, beforeId, afterId) {
  return db.transaction(async (tx) => {
    // Get the card we're moving
    const card = await tx.one('SELECT * FROM cards WHERE id = $1', [cardId]);

    if (!card) {
      throw new Error('Card not found');
    }

    // Remove the card from its current column
    await tx.exec('DELETE FROM cards WHERE id = $1', [cardId]);

    // Get the new position for the card in the target column
    let newPosition;

    if (beforeId && afterId) {
      // This should not happen as per our API design
      throw new Error('Invalid: both beforeId and afterId provided');
    } else if (beforeId) {
      // Insert before the card with beforeId
      const beforeCard = await tx.one(
        'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
        [beforeId, targetColumnId]
      );

      if (!beforeCard) {
        throw new Error('Before card not found in target column');
      }

      newPosition = (beforeCard.position + 1) / 2;
    } else if (afterId) {
      // Insert after the card with afterId
      const afterCard = await tx.one(
        'SELECT position FROM cards WHERE id = $1 AND column_id = $2',
        [afterId, targetColumnId]
      );

      if (!afterCard) {
        throw new Error('After card not found in target column');
      }

      newPosition = (afterCard.position + 1) / 2;
    } else {
      // Append to the end of the column
      const maxPosition = await tx.oneFirst(
        'SELECT MAX(position) FROM cards WHERE column_id = $1',
        [targetColumnId]
      );

      newPosition = maxPosition ? maxPosition + 1 : 1;
    }

    // Insert the card in its new position
    await tx.exec(
      'INSERT INTO cards (id, column_id, text, position) VALUES ($1, $2, $3, $4)',
      [cardId, targetColumnId, card.text, newPosition]
    );

    // Return the updated card
    return tx.one('SELECT * FROM cards WHERE id = $1', [cardId]);
  });
}

// Handle position collisions or precision exhaustion
export async function renormalizeColumnPositions(columnId) {
  const cards = await db.all('SELECT id, text FROM cards WHERE column_id = $1 ORDER BY position', [columnId]);

  // Renormalize positions to integers
  for (let i = 0; i < cards.length; i++) {
    await db.exec(
      'UPDATE cards SET position = $1 WHERE id = $2',
      [i + 1, cards[i].id]
    );
  }

  // Return the updated cards
  return db.all('SELECT * FROM cards WHERE column_id = $1 ORDER BY position', [columnId]);
}"}

{"path": "/tmp/runs/smokes/seed-q4/kanban-board/interactive/runs/201/app/kanban-board/src/sse.js", "content": "let clients = new Set();

export function initSSE(req, res) {
  const headers = {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive'
  };

  res.writeHead(200, headers);

  const clientId = Date.now();
  const client = res;

  clients.add(client);

  // Send a comment every 15 seconds to keep the connection alive
  const keepAliveInterval = setInterval(() => {
    client.write(': keep-alive\n\n');
  }, 15000);

  client.on('close', () => {
    clients.delete(client);
    clearInterval(keepAliveInterval);
  });

  return clientId;
}

export function broadcastEvent(eventType, data) {
  const eventData = JSON.stringify(data);

  for (const client of clients) {
    try {
      client.write(`event: ${eventType}\n`);
      client.write(`data: ${eventData}\n\n`);
    } catch (error) {
      clients.delete(client);
    }
  }
}"}

{"path": "/tmp/runs/smokes/seed-q4/kanban-board/interactive/runs/201/app/kanban-board/src/server.js", "content": "import express from 'express';
import cors from 'cors';
import { initDB, getBoardState, createCard, moveCard, renormalizeColumnPositions } from './db.js';
import { initSSE, broadcastEvent } from './sse.js';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());

// Serve frontend static files
app.use(express.static(path.join(__dirname, '../frontend/public')));

// Initialize database
let db;

async function startServer() {
  try {
    db = await initDB();
    console.log('Database initialized successfully');

    // Start server
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
}

// API Endpoints

// Get board state
app.get('/api/board', async (req, res) => {
  try {
    const boardState = await getBoardState();
    res.json(boardState);
  } catch (error) {
    res.status(500).json({ error: 'Failed to get board state' });
  }
});

// Create a new card
app.post('/api/cards', async (req, res) => {
  try {
    const { columnId, text } = req.body;

    if (!columnId || !text) {
      return res.status(400).json({ error: 'columnId and text are required' });
    }

    const card = await createCard(columnId, text);

    // Broadcast the card creation
    broadcastEvent('cardCreated', card);

    res.status(201).json(card);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create card' });
  }
});

// Move a card
app.patch('/api/cards/:id/move', async (req, res) => {
  try {
    const { id } = req.params;
    const { columnId, beforeId, afterId } = req.body;

    if (!columnId) {
      return res.status(400).json({ error: 'columnId is required' });
    }

    const card = await moveCard(id, columnId, beforeId, afterId);

    // Broadcast the card movement
    broadcastEvent('cardMoved', { card, columnId });

    res.json(card);
  } catch (error) {
    res.status(500).json({ error: 'Failed to move card' });
  }
});

// Renormalize column positions
app.post('/api/columns/:id/renormalize', async (req, res) => {
  try {
    const { id } = req.params;
    const cards = await renormalizeColumnPositions(id);

    // Broadcast the column update
    broadcastEvent('columnRenormalized', { columnId: id, cards });

    res.json(cards);
  } catch (error) {
    res.status(500).json({ error: 'Failed to renormalize column positions' });
  }
});

// SSE endpoint
app.get('/api/stream', (req, res) => {
  initSSE(req, res);
});

// Start the server
startServer();"}

