    }

    // Send move request to server
    fetch(`/api/cards/${draggedCard.id}/move`, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ 
        columnId: targetColumnId,
        beforeId: beforeId,
        afterId: afterId
      }),
    })
    .then(response => response.json())
