        const tempCardIndex = column.cards.findIndex(c => 
          c.id.startsWith('temp-') && c.text === card.text
        );

        if (tempCardIndex !== -1) {
          column.cards[tempCardIndex] = card;
        } else {
          // Add the new card to the end of the column
          column.cards.push(card);
        }

        renderBoard();
      }
    });

