        const afterIndex = targetColumn.cards.findIndex(c => c.id === afterId);
        if (afterIndex !== -1) {
          targetColumn.cards.splice(afterIndex + 1, 0, { ...draggedCard, column_id: targetColumnId });
        } else {
          targetColumn.cards.push({ ...draggedCard, column_id: targetColumnId });
        }
      } else {
        targetColumn.cards.push({ ...draggedCard, column_id: targetColumnId });
      }

      renderBoard();
    }

