        sourceColumn.cards.push(draggedCard);
      }

      if (targetColumn) {
        const tempIndex = targetColumn.cards.findIndex(c => c.id === draggedCard.id);
        if (tempIndex !== -1) {
          targetColumn.cards.splice(tempIndex, 1);
        }
      }

